package dev.eugheist.ttmodern;
final class AwakenedBootsWorldClientAudit {
 static volatile boolean checked;static net.minecraft.world.item.ItemStack previous;static boolean status;static double oldStep;
 static void tick(net.minecraft.client.Minecraft mc,int tick){
  if(tick==770){oldStep=mc.player.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.STEP_HEIGHT).getBaseValue();mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());previous=p.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.FEET).copy();status=AwakenedArmorStatus.enabled(p);AwakenedArmorStatus.set(p,true);net.neoforged.neoforge.network.PacketDistributor.sendToPlayer(p,new AwakenedArmorStatus.Payload(true));p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.FEET,new net.minecraft.world.item.ItemStack(AwakenedBoots.ITEM.get()));});}
  if(tick==785){EnchanterClientAudit.check(mc.player.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.FEET).is(AwakenedBoots.ITEM.get()),"awakened boots native equipment packet");EnchanterClientAudit.check(mc.player.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.STEP_HEIGHT).getBaseValue()==1,"awakened boots native client step height one");mc.player.input.shiftKeyDown=true;mc.player.setShiftKeyDown(true);AwakenedBoots.update(mc.player);EnchanterClientAudit.check(mc.player.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.STEP_HEIGHT).getBaseValue()==.5,"original sneaking step height half");mc.player.input.shiftKeyDown=false;mc.player.setShiftKeyDown(false);AwakenedBoots.update(mc.player);EnchanterClientAudit.check(mc.player.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.STEP_HEIGHT).getBaseValue()==1,"standing step restored");mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());AwakenedArmorItem.toggle(p.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.FEET));});}
  if(tick==800){EnchanterClientAudit.check(AwakenedArmorItem.disabled(mc.player.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.FEET))&&mc.player.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.STEP_HEIGHT).getBaseValue()==oldStep,"native toggle sync restores original client step attribute");mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.FEET,previous);AwakenedArmorStatus.set(p,status);p.removeEffect(net.minecraft.world.effect.MobEffects.DIG_SPEED);checked=true;System.out.println("TT AWAKENED BOOTS WORLD CLIENT AUDIT: ALL PASS (native equipment/toggle packets,standing/sneaking step height,attribute restoration,restored equipment)");});}
 }
}
